INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(128191, 'ruRU', '', 'Жизнь в Долине Четырёх Ветров обычно такая мирная, и для большинства это хорошо. Но для меня это ещё и довольно скучно. Я бы предпочла немного азарта время от времени.', 24330),
(128192, 'ruRU', '', 'Я могу сварить хорошее пиво с закрытыми глазами. А вот Прядение туманов - это вызов. Надеюсь, однажды я стану в этом мастером.', 24330),
(128194, 'ruRU', '', 'Нам нужно вернуться в Храм Пяти Рассветов! Дай мне знать, когда будешь готов!', 24330),
(128198, 'ruRU', '', 'Дредлорд напал на меня, отравил моё Праздничное пиво и украл мой облик...', 24330),
(128202, 'ruRU', '', 'Я пойду с тобой, Великий мастер. Нам нельзя терять время!', 24330),
(128203, 'ruRU', '', '|TInterface\\Icons\\INV_Misc_Herb_Arrowbloom.blp:20|t%s направляет на тебя |cFFFF0000|Hspell:236304|h[Бесплотный выстрел]|h|r!', 24330),
(128204, 'ruRU', '', 'Я должен быть способен повторно активировать их портал. Это место кишит пригодными душами.', 24330),
(128205, 'ruRU', '', 'Я прослежу, чтобы больше никто из прислужников Круула не прошёл. Страдай как следует.', 24330),
(128209, 'ruRU', '', 'Готов раскрыть наше секретное оружие?', 24330),
(128210, 'ruRU', '', 'Все эти демоны... ба! У нас нет шанса быть сломленными, пока мы управляем силой Даумир и её выводка.', 24330),
(128211, 'ruRU', '', 'Легион содрогнётся под тенью Даумир. Они будут умолять о милосердии, пока мы обрушиваем на них смерть и разрушение!', 24330),
(128212, 'ruRU', '', 'Видишь Всадников? Невероятно, что они держатся против такой толпы.', 24330),
(128213, 'ruRU', '', 'Ещё одна партия повержена! Отправь их в могилы!', 24330),
(128214, 'ruRU', '', 'Всадники удержали этих демонов.', 24330),
(128215, 'ruRU', '', 'Даумир быстро с ними расправилась. Слышал их вопли? Музыка для моих ушей!', 24330),
(128216, 'ruRU', '', 'Я никогда не чувствовала себя настолько живой!', 24330),
(128218, 'ruRU', '', 'Приветствую, Убийца $p, на месте размножения осквернённых нетопырей. Мы поймали прекрасный экземпляр, чтобы ты сегодня с ним связался.$b$bПросто сообщи мне, когда будешь готов его увидеть.', 24330),
(128219, 'ruRU', '', 'Иллидари! Выведите зверя!', 24330),
(128220, 'ruRU', '', 'Несколько дней назад этот осквернённый нетопырь напал на наш лагерь. Поймать зрелую особь - редкая удача, так что я настояла на том, чтобы его сковали, а не уничтожили.', 24330),
(128221, 'ruRU', '', 'Укрощение такого своевольного зверя требует демонстрации доминирования. Это, конечно, моя специализация... но в данном случае я предлагаю просто избить его до покорности.', 24330),
(128222, 'ruRU', '', 'Быстро, свяжите существо!', 24330),
(128223, 'ruRU', '', 'Мои извинения, Убийца, похоже, оно сбежало. Ах, но смотри-ка сюда? След крови. Как удобно!', 24330),
(128224, 'ruRU', '', 'Выследить его должно быть просто благодаря твоему демоническому зрению. Но если оно убежало к месту размножения, боюсь, у тебя могут быть проблемы с тем, чтобы вернуть его обратно. Нетопыри бывают такими... норовистыми созданиями.', 24330),
(128230, 'ruRU', '', 'Это... не похоже на правду. Где я?', 24330),
(128233, 'ruRU', '', 'Вижу, ты укротил зверя, Убийца $p. Поздравления уместны, дорогой мой!', 24330),
(128234, 'ruRU', '', 'Позволь нам привести существо в надлежащий вид, чтобы оно могло быть передано тебе на Кузне Скверны. Поговори с Ирдрисом, и он доставит тебя обратно на корабль.', 24330),
(128235, 'ruRU', '', 'У меня ещё есть дела здесь, но я встречу тебя на Кузне Скверны, Убийца $p.', 24330),
(128273, 'ruRU', '', 'Ты выглядишь так, будто что-то потерял. Могу я помочь?', 24330),
(128274, 'ruRU', '', 'Энергия в этом месте злонамеренная. Идём!', 24330),
(128315, 'ruRU', '', 'Надо же, похоже, Агата наткнулась на ещё одну забавную игрушку.', 24330),
(128317, 'ruRU', '', 'Отойди, пока мы вливаем травы в пиво...', 24330),
(128318, 'ruRU', '', 'Вот! Готово.', 24330),
(128319, 'ruRU', '', 'Не волнуйся, Урлия - этот выглядит бодрым. Конечно, $Ghe:she; не сдастся так легко.', 24330),
(128320, 'ruRU', '', 'Давай поиграем, $c!', 24330),
(128321, 'ruRU', '', 'Надеюсь, этот окажется более занятным, чем последний.', 24330),
(128322, 'ruRU', '', 'Агата... будет... довольна...', 24330),
(128323, 'ruRU', '', 'Это было... изысканно...', 24330),
(128328, 'ruRU', '', 'Благословения тебе, Великий мастер!', 24330),
(128329, 'ruRU', '', 'Я была так слаба... Спасибо, что помог мне!', 24330),
(128330, 'ruRU', '', 'Бее! Никогда не думала, что буду рада попробовать что-то настолько отвратительное!', 24330);
